def process(freshwaterBeachExceedanceRates) -> pd.DataFrame:
    import pandas as pd

    df = freshwaterBeachExceedanceRates.copy()
    years = df.loc[df["aboveAvg"] == True, ["year"]].dropna().astype({"year": int}).sort_values("year")
    return years.reset_index(drop=True)
